const detail = $json.detail.toLowerCase();

let nome = null;
let email = null;

if (detail.includes('nome')) {
  nome = $json.detail.split(':').slice(1).join(':').trim();
}

if (detail.includes('@')) {
  email = $json.detail.split(':').slice(1).join(':').trim();
}

return {
  nome,
  email
};

