const items = $input.all();
const output = [];

for (const item of items) {
  const raw = item.json.message || "";

  // Divide por parágrafos (linha em branco entre blocos)
  let blocks = raw
    .split(/\n\s*\n/)
    .map(b => b.trim())
    .filter(b => b.length > 0);

  // Funde blocos curtos demais (ex: só um emoji) com o anterior, pra não
  // virar uma mensagem "solta" estranha
  const MIN_CHARS = 6;
  const merged = [];
  for (const b of blocks) {
    if (merged.length > 0 && b.length < MIN_CHARS) {
      merged[merged.length - 1] += "\n" + b;
    } else {
      merged.push(b);
    }
  }
  blocks = merged;

  // Limita a no máximo 3 mensagens seguidas, pra não virar spam.
  // Se tiver mais blocos que isso, junta o excedente no último.
  const MAX_BLOCKS = 3;
  if (blocks.length > MAX_BLOCKS) {
    const head = blocks.slice(0, MAX_BLOCKS - 1);
    const tail = blocks.slice(MAX_BLOCKS - 1).join("\n\n");
    blocks = [...head, tail];
  }

  if (blocks.length === 0) {
    blocks = [raw];
  }

  blocks.forEach((block, index) => {
    output.push({
      json: {
        ...item.json,
        messageBlock: block,
        blockIndex: index,
        totalBlocks: blocks.length
      }
    });
  });
}

return output;
